CREATE TABLE IF NOT EXISTS cie10_codes (
  code TEXT PRIMARY KEY,
  description TEXT NOT NULL,
  chapter TEXT NULL,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS patient_diagnoses (
  id UUID PRIMARY KEY,
  patient_id UUID NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  cie10_code TEXT NOT NULL REFERENCES cie10_codes(code),
  kind TEXT NOT NULL DEFAULT 'primary' CHECK (kind IN ('primary', 'secondary')),
  status TEXT NOT NULL DEFAULT 'suspected' CHECK (status IN ('suspected', 'confirmed', 'resolved')),
  diagnosed_at DATE NOT NULL DEFAULT CURRENT_DATE,
  notes TEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by_email TEXT NULL,
  created_by_role TEXT NULL,
  updated_by_email TEXT NULL,
  updated_by_role TEXT NULL
);

CREATE INDEX IF NOT EXISTS idx_cie10_codes_description
  ON cie10_codes USING gin (to_tsvector('spanish', description));

CREATE INDEX IF NOT EXISTS idx_patient_diagnoses_patient
  ON patient_diagnoses(patient_id, diagnosed_at DESC);

CREATE INDEX IF NOT EXISTS idx_patient_diagnoses_cie10
  ON patient_diagnoses(cie10_code);

ON CONFLICT (code) DO UPDATE SET
  description = EXCLUDED.description,
  chapter = EXCLUDED.chapter,
  active = EXCLUDED.active,
  updated_at = now();

-- +goose Down
DROP TABLE IF EXISTS patient_diagnoses;
DROP TABLE IF EXISTS cie10_codes;
